Gate every active-tab file-I/O path on `tab.kind` and no-op (or alert) when the kind is `.insight`. Specifically:
```swift
// saveActiveFile (L1149)
func saveActiveFile() {
    guard activeTabIndex >= 0 && activeTabIndex < openTabs.count else { return }
    if case .insight = openTabs[activeTabIndex].kind { return }   // insight is ephemeral
    saveFile(at: activeTabIndex)
}

// reloadActiveTabFromDisk (L1664)
func reloadActiveTabFromDisk() -> String? {
    let idx = activeTabIndex
    guard idx >= 0 && idx < openTabs.count else { return nil }
    if case .insight = openTabs[idx].kind { return nil }
    ...
}

// updateActiveTabContent (L1635) — also gate; insight tab content is owned by InsightSession
func updateActiveTabContent(_ content: String) {
    tabsStore.updateActiveTab { tab in
        if case .insight = tab.kind { return }
        tab.content = content
        tab.isModified = (content != tab.originalContent)
    }
}
```
Additionally, add the same kind-gate at `saveFile(at:)` itself as defense-in-depth (the private helper currently trusts the caller). Audit any other `openTabs[i].url`/`openTabs[i].content` consumer on the same active-tab path and apply the same gate (e.g., `reindexActiveFile` single-file branch L1576-1579, scrollPosition writes are harmless).

Replace the unicode-permissive predicate with an ASCII-only check matching the spec's `[A-Za-z0-9_]`:
```swift
private static func sanitizeInsightFilename(_ title: String) -> String {
    let allowed = Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_")
    let mapped = String(title.map { allowed.contains($0) ? $0 : "_" })
    let collapsed = mapped
        .split(separator: "_", omittingEmptySubsequences: true)
        .joined(separator: "_")
    return collapsed.isEmpty ? "insight" : collapsed
}
```
Additionally consider explicitly rejecting `.` and `..` even if they cannot occur after the predicate (defense-in-depth) and capping the result length to e.g. 200 characters to avoid HFS+/APFS edge cases at 255 bytes.

Validate or truncate sessionId before logging:
```swift
private static func safeSessionId(_ s: String) -> String {
    if let _ = UUID(uuidString: s) { return s }
    return "<invalid:\(s.prefix(16))…>"
}
// usage
NSLog("[Insight] didRequestInsightDeepDive: no session for id %@ (tab closed?)", Self.safeSessionId(sessionId))
```
Use `%@` format specifier rather than string interpolation to defang any `%` payload bytes. Apply the same to `nodeId` in the breadcrumb forwarder. Cap length to 64 characters defensively. (Note: with the fix, `findInsightSession` could short-circuit on `UUID(uuidString:)` failure, since the lookup compares `session.id.uuidString` which is always a valid UUID.)

